#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <glib.h>
int main (int argc, char *argv[])
{
  char *path;
  char *s;
  guint n;
  gboolean opt_user = FALSE;
  /* parse options; stop at the first non-option argument */
  for (n = 1; n < (guint) argc; n++)
    {
      if (strcmp (argv[n], "--version") == 0)
        {
          printf ("pkexec version 0.105\n");
          exit (0);
        }
      else if (strcmp (argv[n], "--user") == 0)
        opt_user = TRUE;
      else
        break;
    }
  path = g_strdup (argv[n]);
  if (path[0] != '/')
    {
      s = g_find_program_in_path (path);
      if (s == NULL)
        exit (127);
      argv[n] = path = s;
    }
  return run_as_root (path, opt_user);
}

